from pyparsing import Regex, Literal, Or, Optional, OneOrMore, Empty
from ute_admin_infomodel.parsing.parser import InfoModelParser


def join_predicate(s, loc, token):
    """Joins parsed predicates into string"""
    if token.quoted:
        return "," + token.name + token.symbol + ' "' + token.value + '"'
    else:
        return " ".join(token.asList())


dist_name = Regex(
    r'(((//)|(/))[A-Z0-9_]+-([1-9]\*\?|0|[1-9][0-9]*|\*|\[(0|[1-9][0-9]*(\,(0|[1-9][0-9]*))*)\]))+')('dist_name')
is_part = Literal('is')

predicate_name = OneOrMore(Regex(r'[^=, >, \], \[, \,, <, <=, >=, !=]+')
                           + Optional(Regex(r"\[(0|[1-9][0-9]*|\*|\?)\]"))).setParseAction(lambda x: ''.join(x))('name')

predicate_without_quotes = Regex(
    r'[^=, >, \], \[, \,, <, <=, >=, !=, "]+')('value')
predicate_with_quotes = Literal('"') + OneOrMore(Regex('[^"]+')).setParseAction(
    lambda x: ' '.join(x))('value') + Literal('"')('quoted')
predicate_value = (predicate_without_quotes | predicate_with_quotes)

symbol = Or((Literal("=regex"), Literal("!=regex"), Literal('>'), Literal(
    '<'), Literal('>='), Literal('<='), Literal('='), Literal('!=')))('symbol')
empty_symbol = Literal("=empty")('symbol')
non_empty_symbol = Literal("!=empty")('symbol')
empty_value = Empty().setParseAction(lambda x: "")('value')

predicate_body = predicate_name + (((empty_symbol | non_empty_symbol) + empty_value) | (symbol + predicate_value))

predicate_content = (Optional(Literal(',')) + predicate_body).setResultsName('predicates', True)
predicate_content_joined = (Optional(Literal(','))
                            + predicate_body).setParseAction(join_predicate).setResultsName('predicates_joined', True)
predicates = Literal('[') + OneOrMore(predicate_content_joined) + Literal(']')

condition_value = Regex('(0|[1-9][0-9]*)')('value')
condition = (symbol + condition_value)('condition')


every = Literal('every')('function')
check = Literal('check')('function')
count = Literal('count')('function')
get_list = Literal('get list')('function')
get_count = Literal('get count')('function')
get_object = Literal('get object')('function')
none = Literal('none')('function')


DistNameGrammar = dist_name
DistNameWithPredicateGrammar = dist_name + is_part + predicates
EveryGrammar = every + DistNameWithPredicateGrammar
CheckGrammar = check + dist_name + Optional(is_part + predicates)
NoneGrammar = none + dist_name + Optional(is_part + predicates)
CountGrammar = count + dist_name + is_part + Optional(predicates) + condition
GetListGrammar = get_list + dist_name + Optional(is_part + predicates)
GetCountGrammar = get_count + dist_name + is_part + Optional(predicates)
GetObjectGrammar = get_object + dist_name + Optional(is_part + predicates)


class InfoModelQueryParser(InfoModelParser):

    def __init__(self):
        self.grammar = (Regex('^')
                        + Or((DistNameGrammar,
                             DistNameWithPredicateGrammar,
                             EveryGrammar,
                             CheckGrammar,
                             NoneGrammar,
                             CountGrammar,
                             GetListGrammar,
                             GetCountGrammar,
                             GetObjectGrammar))
                        + Regex('$'))


class InfoModelPredicateParser(InfoModelParser):
    def __init__(self):
        self.grammar = (Regex('^')
                        + predicate_content
                        + Regex('$'))


class InfoModelConditionParser(InfoModelParser):
    def __init__(self):
        self.grammar = (Regex('^')
                        + condition
                        + Regex('$'))
